beforeSaveCustomScript:
// Quote: logica prezzi/nome in PHP (CreateContratto + SyncContractPricing).
// Formula minima: solo importoSaldo senza finanziamento.

if (hookVersion == null || !string\contains(hookVersion, 'CreateContratto')) {
  if (!finanziamento) {
    importoLordoSaldo = importoContratto;
    if (importoLordoSaldo == null || importoLordoSaldo == 0) {
      importoLordoSaldo = amount;
    }
    caparraSaldo = importoCaparra;
    if (caparraSaldo == null) {
      caparraSaldo = 0;
    }
    if ((importoSaldo == null || importoSaldo == 0) && importoLordoSaldo != null) {
      importoSaldo = importoLordoSaldo - caparraSaldo;
    }
  }
}
